class Deduper:
    def __init__(self, window):
        self.window = window
        self._seen = {}  # Stores {key: last_seen_timestamp}

    def seen(self, key, timestamp):
        # Remove old entries
        keys_to_remove = []
        for k, last_seen_ts in self._seen.items():
            # If an event is older than the window, remove it.
            # An event exactly 'window' seconds ago should NOT be removed yet.
            # So, if timestamp - last_seen_ts > window, it's too old.
            if timestamp - last_seen_ts > self.window:
                keys_to_remove.append(k)
        for k in keys_to_remove:
            del self._seen[k]

        # Check if the current key is a duplicate
        if key not in self._seen:
            self._seen[key] = timestamp
            return False # New event

        last_seen = self._seen[key]

        # If the event arrived exactly one window later, it should be considered new.
        # This means if timestamp - last_seen == window, it's new.
        # So, if timestamp - last_seen < window, it's a duplicate.
        if timestamp - last_seen < self.window:
            # It's a duplicate if it arrived strictly *before* the window expired.
            return True # Duplicate event
        else:
            # It's new if it arrived exactly at the window or after.
            self._seen[key] = timestamp # Update timestamp
            return False # New event
